-- NEW HORIZONS | PostgreSQL | Página 2 del diagrama
-- INSTALACIÓN NUEVA. Ejecutar completo en una base de datos existente.
-- No incluye huellas, datos de prueba ni catálogos precargados.
-- No incluye CREATE INDEX manuales; ver 04_indices_opcionales.sql.
-- PRIMARY KEY y UNIQUE sí crean índices implícitos necesarios para sus restricciones.
-- Si el esquema ya existe, el script falla: no elimina ni reemplaza datos.
-- Si una ejecución anterior dejó la transacción abortada, ejecutar ROLLBACK antes.
-- DDL revisado estructuralmente; no ejecutado contra un servidor PostgreSQL.
--
-- CONVENCIONES
-- bigint identity: identificador numérico generado automáticamente; admite valores explícitos.
-- Las FK usan bigint para coincidir con las PK referenciadas.
-- NOT NULL: campo obligatorio. Su ausencia permite NULL (dato no disponible).
-- bool: true/false/NULL; NULL no equivale a false.
-- varchar(n): texto con límite n; text: texto sin límite declarado.
-- date: fecha sin hora. timestamptz: instante con zona, mostrado según zona de sesión.
-- numeric(12,2): hasta 10 dígitos enteros y 2 decimales. jsonb: JSON estructurado.
-- UNIQUE admite varios NULL; los valores informados deben ser distintos.
-- CHECK valida la fila; una expresión desconocida por NULL no rechaza la fila.
-- Las relaciones se agregan después de crear todas las tablas para evitar dependencias de orden.
-- No se definen borrados en cascada ni triggers; ver limitaciones en la documentación.

BEGIN;
CREATE SCHEMA new_horizons;
SET LOCAL search_path TO new_horizons;
-- BENEFICIARIA
-- Datos personales, salud, ocupación, escolaridad y origen de la beneficiaria.
CREATE TABLE beneficiaria (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_beneficiaria bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.
    cui varchar(20),
    -- Nombre.
    nombre varchar(60) NOT NULL,
    -- Fecha de nacimiento; no se calcula ni almacena edad automáticamente.
    fecha_nac date,
    -- Indicador de alfabetismo; NULL representa dato desconocido.
    alfabetismo bool,
    -- Indicador reportado de enfermedad permanente; NULL representa dato desconocido.
    enfermedad_permanente bool,
    -- Nombre enfermedad.
    nombre_enfermedad varchar(50),
    -- Tipo tratamiento.
    tipo_tratamiento varchar(100),
    -- Otros padecimientos.
    otros_padecimientos varchar(100),
    -- Referencia a pais.pais_id.
    pais_cui_id bigint,
    -- Referencia a tipo_acompanante.tipo_acompanante_id.
    tipo_acompanante_id bigint,
    -- Referencia a lugar_ocupacion.lugar_ocupacion_id.
    lugar_ocupacion_id bigint,
    -- Referencia a estado_civil.estado_civil_id.
    estado_civil_id bigint,
    -- Referencia a ocupacion.ocupacion_id.
    ocupacion_id bigint,
    -- Referencia a nivel_estudio.nivel_estudio_id.
    nivel_estudio_id bigint,
    -- Referencia a residencia.id_residencia.
    residencia_id bigint,
    -- Referencia a pais.pais_id.
    pais_origen_id bigint,
    -- Referencia a departamento.departamento_id.
    departamento_origen_id bigint,
    -- Referencia a municipio.municipio_id.
    municipio_origen_id bigint,
    -- Referencia a estado_estudio.estado_estudio_id.
    estado_estudio_id bigint
);

-- PAIS
-- Catálogo de países, usado para identificación, origen y residencia.
CREATE TABLE pais (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    pais_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(25)
);

-- DEPARTAMENTO
-- División territorial perteneciente a un país.
CREATE TABLE departamento (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    departamento_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(25),
    -- Referencia a pais.pais_id.
    pais_id bigint NOT NULL,
    -- Clave alternativa necesaria para las referencias geográficas compuestas.
    UNIQUE (departamento_id, pais_id)
);

-- MUNICIPIO
-- División territorial perteneciente a un departamento.
CREATE TABLE municipio (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    municipio_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(25),
    -- Referencia a departamento.departamento_id.
    departamento_id bigint NOT NULL,
    -- Clave alternativa necesaria para las referencias geográficas compuestas.
    UNIQUE (municipio_id, departamento_id)
);

-- RESIDENCIA
-- Dirección y datos de contacto asociados a la residencia de la beneficiaria.
CREATE TABLE residencia (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_residencia bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Direccion actual.
    direccion_actual varchar(60),
    -- Número o designación de casa; texto porque puede contener letras o guiones.
    num_casa varchar(8),
    -- Num celular.
    num_celular varchar(25),
    -- Direccion alternativa.
    direccion_alternativa varchar(60),
    -- Persona enlace.
    persona_enlace varchar(40),
    -- Relacion persona enlace.
    relacion_persona_enlace varchar(40),
    -- Indicador de entorno urbano; NULL representa dato desconocido.
    urbano bool,
    -- Referencia a pais.pais_id.
    pais_residencia_id bigint,
    -- Referencia a departamento.departamento_id.
    departamento_residencia_id bigint,
    -- Referencia a municipio.municipio_id.
    municipio_residencia_id bigint,
    -- Referencia a area_residencial.id_area_residencial.
    area_residencial_id bigint
);

-- AREA_RESIDENCIAL
-- Detalles del sector residencial; sus campos pueden coexistir y son opcionales.
CREATE TABLE area_residencial (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_area_residencial bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Colonia.
    colonia varchar(25),
    -- Barrio popular.
    barrio_popular varchar(25),
    -- Asentamiento.
    asentamiento varchar(25),
    -- Designación de zona como texto; permite ceros iniciales y códigos alfanuméricos.
    zona varchar(10),
    -- Aldea.
    aldea varchar(25),
    -- Caserio.
    caserio varchar(25),
    -- Canton.
    canton varchar(25),
    -- Otro.
    otro varchar(25)
);

-- LUGAR_OCUPACION
-- Lugar de trabajo u ocupación y persona de contacto.
CREATE TABLE lugar_ocupacion (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    lugar_ocupacion_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(50),
    -- Direccion.
    direccion varchar(60),
    -- Telefono.
    telefono varchar(25),
    -- Persona contacto.
    persona_contacto varchar(50),
    -- Cargo persona contacto.
    cargo_persona_contacto varchar(50)
);

-- NIVEL_ESTUDIO
-- Catálogo del nivel educativo alcanzado.
CREATE TABLE nivel_estudio (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    nivel_estudio_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40)
);

-- OCUPACION
-- Catálogo de ocupaciones de las beneficiarias.
CREATE TABLE ocupacion (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    ocupacion_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40)
);

-- ETNIA
-- Catálogo de pertenencias étnicas.
CREATE TABLE etnia (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    etnia_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40)
);

-- ESTADO_CIVIL
-- Catálogo de estados civiles.
CREATE TABLE estado_civil (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    estado_civil_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40)
);

-- TIPO_ACOMPANANTE
-- Catálogo del tipo de acompañante; no identifica personas concretas.
CREATE TABLE tipo_acompanante (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    tipo_acompanante_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40)
);

-- OBJETO_AGRESOR
-- Catálogo de objetos relacionados con agresiones.
CREATE TABLE objeto_agresor (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    objeto_agresor_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40),
    -- Descripcion.
    descripcion varchar(100)
);

-- AGRESOR
-- Datos reportados del agresor; admite datos parciales salvo el nombre.
CREATE TABLE agresor (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    agresor_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(60) NOT NULL,
    -- Descripción libre de la ocupación del agresor, conservada del diagrama.
    ocupacion varchar(50),
    -- Lugar trabajo.
    lugar_trabajo varchar(50),
    -- Telefono.
    telefono varchar(25),
    -- Descripción libre del domicilio del agresor; no comparte el domicilio de la beneficiaria.
    lugar_residencia varchar(40),
    -- Monto mensual no negativo, con dos decimales; moneda pendiente de definición.
    ingreso_mensual numeric(12,2),
    -- Edad reportada al registrar al agresor, en años; rango 0–130; NULL si se desconoce.
    edad smallint,
    -- Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.
    cui varchar(20),
    -- Horario trabajo.
    horario_trabajo varchar(50),
    -- Referencia a parentesco.parentesco_id. Vínculo reportado conservado en agresor. Si depende de cada beneficiaria debe trasladarse a la relación con ficha.
    parentesco_id bigint,
    -- Valida el rango, la secuencia de fechas o impide autosupervisión según la expresión.
    CHECK (edad BETWEEN 0 AND 130),
    -- Valida el rango, la secuencia de fechas o impide autosupervisión según la expresión.
    CHECK (ingreso_mensual >= 0)
);

-- EMPLEADO
-- Personal de la organización, rol y supervisor opcional.
CREATE TABLE empleado (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_empleado bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(60) NOT NULL,
    -- Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.
    cui varchar(20),
    -- Referencia a empleado.id_empleado.
    supervisor bigint,
    -- Referencia a rol.id_rol.
    rol_id bigint,
    -- Valida el rango, la secuencia de fechas o impide autosupervisión según la expresión.
    CHECK (supervisor IS NULL OR supervisor <> id_empleado)
);

-- AGRESIONES
-- Catálogo de agresiones; se mantiene separado del tipo de violencia.
CREATE TABLE agresiones (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    agresiones_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40),
    -- Descripcion.
    descripcion varchar(200)
);

-- PARENTESCO
-- Catálogo de vínculos o parentescos.
CREATE TABLE parentesco (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    parentesco_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40)
);

-- APOYO_RECIBIDO
-- Registro del apoyo recibido, lugar, fecha y dato de denuncia.
CREATE TABLE apoyo_recibido (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    apoyo_recibido_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Lugar.
    lugar varchar(40),
    -- Tipo.
    tipo varchar(50),
    -- Fecha.
    fecha date,
    -- Indicador de denuncia reportada; NULL representa dato desconocido.
    denuncia bool
);

-- DURACION_AGRESION
-- Catálogo de duraciones o períodos reportados de agresión.
CREATE TABLE duracion_agresion (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    duracion_agresion_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40),
    -- Descripcion.
    descripcion varchar(80)
);

-- SITUACION_RIESGO
-- Catálogo de situaciones de riesgo identificadas.
CREATE TABLE situacion_riesgo (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    situacion_riesgo_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(40),
    -- Descripcion.
    descripcion varchar(200)
);

-- TIPO_VIOLENCIA
-- Catálogo de tipos de violencia.
CREATE TABLE tipo_violencia (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    tipo_violencia_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Tipo.
    tipo varchar(40),
    -- Descripcion.
    descripcion varchar(200)
);

-- REFERENCIA_EXTERNA
-- Catálogo de referencias o derivaciones externas.
CREATE TABLE referencia_externa (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    referencia_externa_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Tipo.
    tipo varchar(50),
    -- Descripcion.
    descripcion varchar(200)
);

-- REFERENCIA_INTERNA
-- Catálogo de referencias o derivaciones internas.
CREATE TABLE referencia_interna (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    referencia_interna_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Tipo.
    tipo varchar(50),
    -- Descripcion.
    descripcion varchar(200)
);

-- PERMISOS
-- Catálogo de acciones autorizables en la aplicación.
CREATE TABLE permisos (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_permisos bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Tipo permisos.
    tipo_permisos varchar(20)
);

-- RECURSOS
-- Catálogo de recursos de la aplicación sujetos a permisos.
CREATE TABLE recursos (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_recursos bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Tipo recursos.
    tipo_recursos varchar(40),
    -- Link.
    link varchar(100)
);

-- NINO
-- Niño o niña relacionado con una beneficiaria, sin vinculación a una estancia concreta.
CREATE TABLE nino (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    nino_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.
    cui varchar(20),
    -- Nombre.
    nombre varchar(60),
    -- Fecha de nacimiento; no se calcula ni almacena edad automáticamente.
    fecha_nac date,
    -- Indicador de reconocimiento según el formulario original; significado legal no inferido.
    reconocido bool,
    -- Código de un carácter heredado del diagrama; catálogo de valores pendiente de definición.
    genero varchar(1),
    -- Referencia a beneficiaria.id_beneficiaria.
    beneficiaria_id bigint NOT NULL
);

-- ACTIVOS_ALBERGUE
-- Registro de una estancia de beneficiaria en el albergue; permite historial.
CREATE TABLE activos_albergue (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    activo_albergue_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Fecha de inicio de la estancia, obligatoria.
    fecha_ingreso date NOT NULL,
    -- Fecha de fin de estancia, opcional; no puede anteceder al ingreso.
    fecha_egreso date,
    -- Referencia a beneficiaria.id_beneficiaria.
    beneficiaria_id bigint NOT NULL,
    -- Referencia a estado_albergue.estado_albergue_id.
    estado_albergue_id bigint,
    -- Valida el rango, la secuencia de fechas o impide autosupervisión según la expresión.
    CHECK (fecha_egreso IS NULL OR fecha_egreso >= fecha_ingreso)
);

-- ROL_PERMISOS_POR_RECURSO
-- Asigna un permiso a un rol sobre un recurso concreto.
CREATE TABLE rol_permisos_por_recurso (
    -- Referencia a rol.id_rol.
    id_rol bigint NOT NULL,
    -- Referencia a permisos.id_permisos.
    id_permisos bigint NOT NULL,
    -- Referencia a recursos.id_recursos.
    id_recursos bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_rol, id_permisos, id_recursos)
);

-- MOVIMIENTO_ALBERGUE
-- Salida temporal y regreso asociados a una estancia en el albergue.
CREATE TABLE movimiento_albergue (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    movimiento_albergue_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Instante de salida temporal, obligatorio, con zona horaria.
    salida timestamptz NOT NULL,
    -- Instante de regreso, opcional; no puede anteceder a la salida.
    entrada timestamptz,
    -- Descripción libre del trabajador asignado, conservada del diagrama; no es FK a empleado.
    trabajador_asignado varchar(200),
    -- Destino.
    destino varchar(100),
    -- Referencia a activos_albergue.activo_albergue_id.
    activo_albergue_id bigint NOT NULL,
    -- Valida el rango, la secuencia de fechas o impide autosupervisión según la expresión.
    CHECK (entrada IS NULL OR entrada >= salida)
);

-- ROL
-- Catálogo de roles de aplicación y su área opcional.
CREATE TABLE rol (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_rol bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Tipo rol.
    tipo_rol varchar(60),
    -- Descripcion.
    descripcion varchar(20),
    -- Referencia a area.id_area.
    id_area bigint
);

-- AREA
-- Catálogo de áreas de atención o trabajo de la organización.
CREATE TABLE area (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_area bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre area.
    nombre_area varchar(60),
    -- Descripcion.
    descripcion varchar(100)
);

-- USUARIO
-- Cuenta de aplicación vinculada a un empleado; almacena hashes generados por la aplicación.
CREATE TABLE usuario (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_usuario bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Identificador de acceso único; la comparación distingue mayúsculas y minúsculas.
    nombre_usuario varchar(60) NOT NULL UNIQUE,
    -- Hash de contraseña producido por la aplicación; nunca la contraseña en texto plano.
    contrasena_hash text NOT NULL,
    -- Referencia a empleado.id_empleado.
    id_empleado bigint NOT NULL,
    -- Hash opcional de token producido por la aplicación; su expiración no se modela.
    token_hash text
);

-- HOJA_EVOLUTIVA
-- Seguimiento de beneficiaria por área, con acciones en JSONB.
CREATE TABLE hoja_evolutiva (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_hoja_evolutiva bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Datos de seguimiento en JSONB; estructura interna pendiente de definición.
    accion jsonb,
    -- Código de hoja evolutiva, único cuando tiene valor; unicidad global asumida.
    correlativo varchar(50) UNIQUE,
    -- Referencia a beneficiaria.id_beneficiaria.
    id_beneficiaria bigint NOT NULL,
    -- Referencia a area.id_area.
    id_area bigint NOT NULL
);

-- REFERENCIA
-- Registro del intermediario, distinto de las derivaciones internas y externas.
CREATE TABLE referencia (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_referencia bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Intermediario.
    intermediario varchar(20)
);

-- FICHA_INICIAL
-- Registro de atención inicial y evaluación de la beneficiaria.
CREATE TABLE ficha_inicial (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    id_ficha_inicial bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Código de ficha inicial, único cuando tiene valor; unicidad global asumida.
    correlativo_ficha varchar(20) UNIQUE,
    -- Lugar.
    lugar varchar(100),
    -- Fecha.
    fecha timestamptz,
    -- Analisis riesgo.
    analisis_riesgo varchar(200),
    -- Plan seguridad.
    plan_seguridad varchar(200),
    -- Entrevista inicial.
    entrevista_inicial varchar(200),
    -- Seguimiento.
    seguimiento varchar(200),
    -- Observaciones.
    observaciones varchar(200),
    -- Referencia a beneficiaria.id_beneficiaria.
    beneficiaria_id bigint NOT NULL,
    -- Referencia a apoyo_recibido.apoyo_recibido_id.
    apoyo_recibido_id bigint,
    -- Referencia a empleado.id_empleado.
    empleado_id bigint,
    -- Referencia a duracion_agresion.duracion_agresion_id.
    duracion_agresion_id bigint,
    -- Referencia a referencia.id_referencia.
    referencia_id bigint
);

-- FICHA_INICIAL_TIPO_VIOLENCIA
-- Relación muchos a muchos entre fichas y tipos de violencia.
CREATE TABLE ficha_inicial_tipo_violencia (
    -- Referencia a ficha_inicial.id_ficha_inicial.
    id_ficha_inicial bigint NOT NULL,
    -- Referencia a tipo_violencia.tipo_violencia_id.
    tipo_violencia_id bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_ficha_inicial, tipo_violencia_id)
);

-- FICHA_INICIAL_SIT_RIESGO
-- Relación muchos a muchos entre fichas y situaciones de riesgo.
CREATE TABLE ficha_inicial_sit_riesgo (
    -- Referencia a ficha_inicial.id_ficha_inicial.
    id_ficha_inicial bigint NOT NULL,
    -- Referencia a situacion_riesgo.situacion_riesgo_id.
    situacion_riesgo_id bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_ficha_inicial, situacion_riesgo_id)
);

-- FICHA_INICIAL_REF_INTERNA
-- Relación muchos a muchos entre fichas y referencias internas.
CREATE TABLE ficha_inicial_ref_interna (
    -- Referencia a ficha_inicial.id_ficha_inicial.
    id_ficha_inicial bigint NOT NULL,
    -- Referencia a referencia_interna.referencia_interna_id.
    referencia_interna_id bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_ficha_inicial, referencia_interna_id)
);

-- FICHA_INICIAL_REF_EXTERNA
-- Relación muchos a muchos entre fichas y referencias externas.
CREATE TABLE ficha_inicial_ref_externa (
    -- Referencia a ficha_inicial.id_ficha_inicial.
    id_ficha_inicial bigint NOT NULL,
    -- Referencia a referencia_externa.referencia_externa_id.
    referencia_externa_id bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_ficha_inicial, referencia_externa_id)
);

-- AGRESOR_AGRESIONES
-- Relación muchos a muchos entre agresores y agresiones reportadas.
CREATE TABLE agresor_agresiones (
    -- Referencia a agresor.agresor_id.
    id_agresor bigint NOT NULL,
    -- Referencia a agresiones.agresiones_id.
    agresiones_id bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_agresor, agresiones_id)
);

-- AGRESOR_OBJETO
-- Relación muchos a muchos entre agresores y objetos.
CREATE TABLE agresor_objeto (
    -- Referencia a agresor.agresor_id.
    id_agresor bigint NOT NULL,
    -- Referencia a objeto_agresor.objeto_agresor_id.
    id_objeto_agresor bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_agresor, id_objeto_agresor)
);

-- BENEFICIARIA_ETNIA
-- Relación muchos a muchos entre beneficiarias y etnias.
CREATE TABLE beneficiaria_etnia (
    -- Referencia a beneficiaria.id_beneficiaria.
    id_beneficiaria bigint NOT NULL,
    -- Referencia a etnia.etnia_id.
    id_etnia bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_beneficiaria, id_etnia)
);

-- AGRESORES_FICHA_INICIAL
-- Relación muchos a muchos entre agresores y fichas iniciales.
CREATE TABLE agresores_ficha_inicial (
    -- Referencia a agresor.agresor_id.
    id_agresor bigint NOT NULL,
    -- Referencia a ficha_inicial.id_ficha_inicial.
    id_ficha_inicial bigint NOT NULL,
    -- La combinación completa no puede repetirse; cada columna de la relación es obligatoria.
    PRIMARY KEY (id_agresor, id_ficha_inicial)
);

-- ESTADO_ESTUDIO
-- Catálogo abierto que sustituye el ENUM estudio sin valores definidos.
CREATE TABLE estado_estudio (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    estado_estudio_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(60)
);

-- ESTADO_ALBERGUE
-- Catálogo abierto que sustituye el ENUM estado de estancia sin valores definidos.
CREATE TABLE estado_albergue (
    -- Clave primaria generada automáticamente; identifica una fila de esta tabla.
    estado_albergue_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Nombre.
    nombre varchar(60)
);

