-- Geografía coherente: departamento exige país y municipio exige departamento.
-- Las FK compuestas verifican que los valores pertenezcan a la misma jerarquía.
ALTER TABLE beneficiaria ADD CHECK (departamento_origen_id IS NULL OR pais_origen_id IS NOT NULL), ADD CHECK (municipio_origen_id IS NULL OR departamento_origen_id IS NOT NULL), ADD FOREIGN KEY (departamento_origen_id, pais_origen_id) REFERENCES departamento (departamento_id, pais_id), ADD FOREIGN KEY (municipio_origen_id, departamento_origen_id) REFERENCES municipio (municipio_id, departamento_id);

-- Geografía coherente: departamento exige país y municipio exige departamento.
-- Las FK compuestas verifican que los valores pertenezcan a la misma jerarquía.
ALTER TABLE residencia ADD CHECK (departamento_residencia_id IS NULL OR pais_residencia_id IS NOT NULL), ADD CHECK (municipio_residencia_id IS NULL OR departamento_residencia_id IS NOT NULL), ADD FOREIGN KEY (departamento_residencia_id, pais_residencia_id) REFERENCES departamento (departamento_id, pais_id), ADD FOREIGN KEY (municipio_residencia_id, departamento_residencia_id) REFERENCES municipio (municipio_id, departamento_id);

-- DESCRIPCIONES PERSISTENTES EN EL CATÁLOGO DE POSTGRESQL
COMMENT ON TABLE beneficiaria IS 'Datos personales, salud, ocupación, escolaridad y origen de la beneficiaria.';
COMMENT ON TABLE pais IS 'Catálogo de países, usado para identificación, origen y residencia.';
COMMENT ON TABLE departamento IS 'División territorial perteneciente a un país.';
COMMENT ON TABLE municipio IS 'División territorial perteneciente a un departamento.';
COMMENT ON TABLE residencia IS 'Dirección y datos de contacto asociados a la residencia de la beneficiaria.';
COMMENT ON TABLE area_residencial IS 'Detalles del sector residencial; sus campos pueden coexistir y son opcionales.';
COMMENT ON TABLE lugar_ocupacion IS 'Lugar de trabajo u ocupación y persona de contacto.';
COMMENT ON TABLE nivel_estudio IS 'Catálogo del nivel educativo alcanzado.';
COMMENT ON TABLE ocupacion IS 'Catálogo de ocupaciones de las beneficiarias.';
COMMENT ON TABLE etnia IS 'Catálogo de pertenencias étnicas.';
COMMENT ON TABLE estado_civil IS 'Catálogo de estados civiles.';
COMMENT ON TABLE tipo_acompanante IS 'Catálogo del tipo de acompañante; no identifica personas concretas.';
COMMENT ON TABLE objeto_agresor IS 'Catálogo de objetos relacionados con agresiones.';
COMMENT ON TABLE agresor IS 'Datos reportados del agresor; admite datos parciales salvo el nombre.';
COMMENT ON TABLE empleado IS 'Personal de la organización, rol y supervisor opcional.';
COMMENT ON TABLE agresiones IS 'Catálogo de agresiones; se mantiene separado del tipo de violencia.';
COMMENT ON TABLE parentesco IS 'Catálogo de vínculos o parentescos.';
COMMENT ON TABLE apoyo_recibido IS 'Registro del apoyo recibido, lugar, fecha y dato de denuncia.';
COMMENT ON TABLE duracion_agresion IS 'Catálogo de duraciones o períodos reportados de agresión.';
COMMENT ON TABLE situacion_riesgo IS 'Catálogo de situaciones de riesgo identificadas.';
COMMENT ON TABLE tipo_violencia IS 'Catálogo de tipos de violencia.';
COMMENT ON TABLE referencia_externa IS 'Catálogo de referencias o derivaciones externas.';
COMMENT ON TABLE referencia_interna IS 'Catálogo de referencias o derivaciones internas.';
COMMENT ON TABLE permisos IS 'Catálogo de acciones autorizables en la aplicación.';
COMMENT ON TABLE recursos IS 'Catálogo de recursos de la aplicación sujetos a permisos.';
COMMENT ON TABLE nino IS 'Niño o niña relacionado con una beneficiaria, sin vinculación a una estancia concreta.';
COMMENT ON TABLE activos_albergue IS 'Registro de una estancia de beneficiaria en el albergue; permite historial.';
COMMENT ON TABLE rol_permisos_por_recurso IS 'Asigna un permiso a un rol sobre un recurso concreto.';
COMMENT ON TABLE movimiento_albergue IS 'Salida temporal y regreso asociados a una estancia en el albergue.';
COMMENT ON TABLE rol IS 'Catálogo de roles de aplicación y su área opcional.';
COMMENT ON TABLE area IS 'Catálogo de áreas de atención o trabajo de la organización.';
COMMENT ON TABLE usuario IS 'Cuenta de aplicación vinculada a un empleado; almacena hashes generados por la aplicación.';
COMMENT ON TABLE hoja_evolutiva IS 'Seguimiento de beneficiaria por área, con acciones en JSONB.';
COMMENT ON TABLE referencia IS 'Registro del intermediario, distinto de las derivaciones internas y externas.';
COMMENT ON TABLE ficha_inicial IS 'Registro de atención inicial y evaluación de la beneficiaria.';
COMMENT ON TABLE ficha_inicial_tipo_violencia IS 'Relación muchos a muchos entre fichas y tipos de violencia.';
COMMENT ON TABLE ficha_inicial_sit_riesgo IS 'Relación muchos a muchos entre fichas y situaciones de riesgo.';
COMMENT ON TABLE ficha_inicial_ref_interna IS 'Relación muchos a muchos entre fichas y referencias internas.';
COMMENT ON TABLE ficha_inicial_ref_externa IS 'Relación muchos a muchos entre fichas y referencias externas.';
COMMENT ON TABLE agresor_agresiones IS 'Relación muchos a muchos entre agresores y agresiones reportadas.';
COMMENT ON TABLE agresor_objeto IS 'Relación muchos a muchos entre agresores y objetos.';
COMMENT ON TABLE beneficiaria_etnia IS 'Relación muchos a muchos entre beneficiarias y etnias.';
COMMENT ON TABLE agresores_ficha_inicial IS 'Relación muchos a muchos entre agresores y fichas iniciales.';
COMMENT ON TABLE estado_estudio IS 'Catálogo abierto que sustituye el ENUM estudio sin valores definidos.';
COMMENT ON TABLE estado_albergue IS 'Catálogo abierto que sustituye el ENUM estado de estancia sin valores definidos.';
COMMENT ON COLUMN beneficiaria.cui IS 'Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.';
COMMENT ON COLUMN beneficiaria.fecha_nac IS 'Fecha de nacimiento; no se calcula ni almacena edad automáticamente.';
COMMENT ON COLUMN beneficiaria.alfabetismo IS 'Indicador de alfabetismo; NULL representa dato desconocido.';
COMMENT ON COLUMN beneficiaria.enfermedad_permanente IS 'Indicador reportado de enfermedad permanente; NULL representa dato desconocido.';
COMMENT ON COLUMN residencia.num_casa IS 'Número o designación de casa; texto porque puede contener letras o guiones.';
COMMENT ON COLUMN residencia.urbano IS 'Indicador de entorno urbano; NULL representa dato desconocido.';
COMMENT ON COLUMN area_residencial.zona IS 'Designación de zona como texto; permite ceros iniciales y códigos alfanuméricos.';
COMMENT ON COLUMN agresor.ocupacion IS 'Descripción libre de la ocupación del agresor, conservada del diagrama.';
COMMENT ON COLUMN agresor.lugar_residencia IS 'Descripción libre del domicilio del agresor; no comparte el domicilio de la beneficiaria.';
COMMENT ON COLUMN agresor.ingreso_mensual IS 'Monto mensual no negativo, con dos decimales; moneda pendiente de definición.';
COMMENT ON COLUMN agresor.edad IS 'Edad reportada al registrar al agresor, en años; rango 0–130; NULL si se desconoce.';
COMMENT ON COLUMN agresor.cui IS 'Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.';
COMMENT ON COLUMN agresor.parentesco_id IS 'Vínculo reportado conservado en agresor. Si depende de cada beneficiaria debe trasladarse a la relación con ficha.';
COMMENT ON COLUMN empleado.cui IS 'Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.';
COMMENT ON COLUMN parentesco.parentesco_id IS 'Vínculo reportado conservado en agresor. Si depende de cada beneficiaria debe trasladarse a la relación con ficha.';
COMMENT ON COLUMN apoyo_recibido.denuncia IS 'Indicador de denuncia reportada; NULL representa dato desconocido.';
COMMENT ON COLUMN nino.cui IS 'Identificador personal como texto; conserva ceros iniciales. Sin unicidad ni formato nacional impuesto.';
COMMENT ON COLUMN nino.fecha_nac IS 'Fecha de nacimiento; no se calcula ni almacena edad automáticamente.';
COMMENT ON COLUMN nino.reconocido IS 'Indicador de reconocimiento según el formulario original; significado legal no inferido.';
COMMENT ON COLUMN nino.genero IS 'Código de un carácter heredado del diagrama; catálogo de valores pendiente de definición.';
COMMENT ON COLUMN activos_albergue.fecha_ingreso IS 'Fecha de inicio de la estancia, obligatoria.';
COMMENT ON COLUMN activos_albergue.fecha_egreso IS 'Fecha de fin de estancia, opcional; no puede anteceder al ingreso.';
COMMENT ON COLUMN movimiento_albergue.salida IS 'Instante de salida temporal, obligatorio, con zona horaria.';
COMMENT ON COLUMN movimiento_albergue.entrada IS 'Instante de regreso, opcional; no puede anteceder a la salida.';
COMMENT ON COLUMN movimiento_albergue.trabajador_asignado IS 'Descripción libre del trabajador asignado, conservada del diagrama; no es FK a empleado.';
COMMENT ON COLUMN usuario.nombre_usuario IS 'Identificador de acceso único; la comparación distingue mayúsculas y minúsculas.';
COMMENT ON COLUMN usuario.contrasena_hash IS 'Hash de contraseña producido por la aplicación; nunca la contraseña en texto plano.';
COMMENT ON COLUMN usuario.token_hash IS 'Hash opcional de token producido por la aplicación; su expiración no se modela.';
COMMENT ON COLUMN hoja_evolutiva.accion IS 'Datos de seguimiento en JSONB; estructura interna pendiente de definición.';
COMMENT ON COLUMN hoja_evolutiva.correlativo IS 'Código de hoja evolutiva, único cuando tiene valor; unicidad global asumida.';
COMMENT ON COLUMN ficha_inicial.correlativo_ficha IS 'Código de ficha inicial, único cuando tiene valor; unicidad global asumida.';

COMMIT;
